    if(!ref||rd>1.5)return;var rb=ref.b,t=rb.max[tx]-rb.min[tx],mid=(rb.min[tx]+rb.max[tx])/2,sk=(meshesById.get(ref.id)||[]).filter(function(m){return m.isMesh&&!m.userData.seam&&!m.userData.edges})[0];if(!sk)return;
